function uni05_plots(out,b,f,large,it,s,sz,tr)
dest=fullfile(out,'figures'); if ~isfolder(dest), mkdir(dest); end; catalog=struct('file',{},'field',{},'meaning',{});
set(groot,'defaultFigureVisible','off','defaultAxesFontSize',20,'defaultTextFontSize',20,'defaultAxesColorOrder',[0 .46 .73;0 .66 .72;.8 .45 .1;.2 .25 .32]);
fig; stairs(0:95,b.tb(1:96),'LineWidth',2); ylim([-.1 1.1]); labels('Transport block input','Bit index','Bit value'); finish('01 Input bits','b.tb','First 96 information bits of the saved transport block');
fig; stairs(0:47,b.withCRC(end-47:end),'LineWidth',2); ylim([0 1.3]); xline(32,'--','CRC16 starts',LabelOrientation='horizontal',LabelVerticalAlignment='top',LabelHorizontalAlignment='right'); labels('End of payload and appended CRC','Local bit index','Bit value'); finish('02 CRC attachment','b.withCRC','The last 16 appended bits protect the whole 1024 bit block');
fig; bar([numel(b.tb) numel(b.withCRC) numel(b.cbs) numel(b.encoded) numel(b.rateMatched{1})]); xticks(1:5); xticklabels({'TB','TB + CRC','CB matrix','LDPC output','RV output'}); labels('Bit counts through the encoder','Processing stage','Stored bit positions'); finish('03 Encoder lengths','b.tb, withCRC, cbs, encoded, rateMatched','Filler and parity change the stored lengths before rate selection');
fig; imagesc(large.cbs); colorbar; xticks(1:2); labels('Segmentation of a 9000 bit block','Code block index','Position in code block'); finish('04 Segmentation matrix','large.cbs','Two actual LDPC input code blocks; filler is marked by -1');
fig; q=sz(sz.R==.5,:); stairs(q.A,q.C,'-o','LineWidth',2); labels('Code block count versus transport length','Transport bits','Code block count'); finish('05 Segmentation threshold','sizes.C','BG and CRC decisions precede the code block count');
fig; for r=[.3 .5 .8],q=sz(sz.R==r,:); stairs(q.A,q.BGN,'-o','LineWidth',2);hold on;end; legend('R=0.3','R=0.5','R=0.8'); labels('Base graph selection','Transport bits','Base graph number'); ylim([.8 2.2]); finish('06 Base graph choice','sizes.BGN','The target rate and block size jointly select BG1 or BG2');
fig; q=sz(sz.R==.5,:); plot(q.A,q.Zc,'-o','LineWidth',2); labels('Lifting size selection','Transport bits','Lifting size'); finish('07 Lifting size','sizes.Zc','Allowed lifting sizes produce discrete changes in code dimensions');
fig; q=sz(sz.R==.5,:); bar(categorical(string(q.A),string(q.A)),q.FillerCount); labels('Filler positions after segmentation','Transport bits','Total filler positions'); finish('08 Filler count','sizes.FillerCount','Filler completes the selected LDPC input dimensions');
fig; stairs(b.encoded(1:160),'LineWidth',2); labels('LDPC output sample','Encoded bit index','Bit value'); finish('09 Encoded bits','b.encoded','Encoded sequence before RV dependent rate matching');
maps=zeros(numel(b.encoded),4); for j=1:4, rr=nrRateRecoverLDPC(ones(b.G,1),b.A,b.R,j-1,'QPSK',1); rr(isinf(rr))=0; maps(:,j)=rr(:); end
fig; imagesc(0:3,1:size(maps,1),maps>0); colorbar; labels('Which encoded positions each RV carries','Redundancy version','Encoded bit position'); finish('10 RV coverage','nrRateRecoverLDPC(ones(G,1))','One marks transmitted positions; filler is excluded');
fig; ov=zeros(4); for j=1:4,for k=1:4,ov(j,k)=sum(maps(:,j)>0&maps(:,k)>0);end;end; imagesc(0:3,0:3,ov); colorbar; labels('Overlap between redundancy versions','Redundancy version','Redundancy version'); finish('11 RV overlap','maps','Counts of encoded positions shared by two transmissions');
fig; coverage=zeros(1,4); v=false(size(maps,1),1); order=[1 3 4 2]; for j=1:4,v=v|maps(:,order(j))>0;coverage(j)=sum(v);end; plot(1:4,coverage,'-o','LineWidth',2); labels('Accumulated distinct encoded positions','Attempt in RV sequence 0,2,3,1','Distinct observed positions'); finish('12 Accumulated coverage','maps','Incremental redundancy exposes new encoded positions');
fig; scatter(real(b.x{1}),imag(b.x{1}),50,'filled'); axis equal; xlim([-1 1]); ylim([-1 1]); labels('Transmitted QPSK symbols','In phase','Quadrature'); finish('13 Modulated symbols','b.x{1}','Rate matched bits map to unit energy QPSK');
fig; scatter(real(f.y{1}),imag(f.y{1}),7,'filled'); axis equal; labels('Received symbols at -3 dB','In phase','Quadrature'); finish('14 Noisy symbols','f.y{1}','Complex AWGN acts independently on each modulation symbol');
fig; histogram(f.llr{1}(f.rateMatched{1}==0),30); hold on; histogram(f.llr{1}(f.rateMatched{1}==1),30); legend('Sent zero','Sent one'); labels('Demodulator likelihood distributions','Log likelihood ratio','Count'); finish('15 Demodulator LLR','f.llr{1}','At low SNR the sign of many likelihoods is wrong');
fig; z=f.recovered{1}; z(isinf(z))=NaN; plot(movmean(abs(z),40,'omitnan'),'LineWidth',2); labels('Rate recovery restores encoded positions','Encoded bit index','Smoothed |LLR| (40-bit window)'); finish('16 Recovered soft buffer','f.recovered{1}','Unsent positions are zero; filler infinities omitted');
fig; z=f.combined{2}; z(isinf(z))=NaN; plot(movmean(abs(z),40,'omitnan'),'LineWidth',2); labels('Soft buffer after two transmissions','Encoded bit index','Smoothed accumulated |LLR| (40-bit window)'); finish('17 Combined soft buffer','f.combined{2}','Independent evidence adds after encoded position alignment');
fig; eb=accumarray(ceil(find(f.tb~=f.decoded{1})/64),1,[16 1]); bar(1:16,eb); xticks(1:16); labels(sprintf('Failed first decoding attempt: %d errors',f.bitErrors(1)),'Block of 64 information bits','Bit errors in block'); finish('18 First decoding errors','f.decoded{1}, f.tb','The CRC failure has observable information bit errors');
fig; plot(1:4,f.bitErrors,'-o','LineWidth',2); labels('Information errors after each RV','Attempt in sequence 0,2,3,1','Bit error count'); finish('19 Errors by attempt','f.bitErrors','Each point is a fresh decoding of the accumulated buffer');
fig; stairs(1:4,double(f.fail),'-o','LineWidth',2); ylim([-.1 1.1]); labels('CRC decisions for the saved failure trace','Attempt','CRC failure indicator'); finish('20 CRC decisions','f.fail','Zero means the transport CRC accepted the decoded block');
fig; for m=1:3,q=s(s.Method==m,:);plot(q.SNRdB,q.FirstFailures./q.Trials,'-o','LineWidth',2);hold on;end;legend('IR','Chase','Reset');labels('Initial transmission block error rate','SNR per QPSK symbol (dB)','First attempt BLER');finish('21 First attempt BLER','summary.FirstFailures','Identical first transmissions give identical first attempt results');
fig; for m=1:3,q=s(s.Method==m,:);p=q.ResidualFailures./q.Trials;errorbar(q.SNRdB,p,p-q.WilsonLow,q.WilsonHigh-p,'-o','LineWidth',2);hold on;end;legend('IR','Chase','Reset');labels('Residual failures after at most four attempts','SNR per QPSK symbol (dB)','Residual BLER with 95% interval');ylim([0 1.05]);finish('22 Residual BLER','summary.ResidualFailures, WilsonLow, WilsonHigh','60 independent transport blocks per SNR and method');
fig; for m=1:3,q=s(s.Method==m,:);plot(q.SNRdB,q.GoodputBitsPerCodedBit,'-o','LineWidth',2);hold on;end;legend('IR','Chase','Reset','Location','northwest');labels('Delivered information per coded bit sent','SNR per QPSK symbol (dB)','Goodput (information bit / coded bit)');finish('23 Goodput','summary.GoodputBitsPerCodedBit','All attempts before acceptance or exhaustion contribute to the denominator');
fig; for m=1:3,q=s(s.Method==m,:);plot(q.SNRdB,q.MeanAttempts,'-o','LineWidth',2);hold on;end;legend('IR','Chase','Reset');labels('Transmission cost per transport block','SNR per QPSK symbol (dB)','Mean used attempts');finish('24 Attempts','summary.MeanAttempts','One attempt is charged even when its block fails');
fig; plot(it(:,1),it(:,2:5),'-o','LineWidth',2);legend('Attempt 1','Attempt 2','Attempt 3','Attempt 4');labels('Decoder iteration limit sensitivity','Maximum iterations','Information bit errors');finish('25 Iteration limit','iterScan','One fixed -1 dB realization; not a population performance claim');
fig; q=tr(tr.Method==1&tr.SNRdB==-3&tr.Attempt==4,:);histogram(q.UsedAttempts,.5:1:4.5);xticks(1:4);labels('HARQ service distribution at -3 dB','Used attempts','Transport block count');finish('26 Service distribution','trials.UsedAttempts','Fourth attempt includes accepted and exhausted blocks');
fid=fopen(fullfile(dest,'catalog.json'),'w');fprintf(fid,'%s',jsonencode(catalog,PrettyPrint=true));fclose(fid);
function fig,pubfig.new('wide');end
function labels(tt,xx,yy),title(tt);xlabel(xx);ylabel(yy);grid on;end
function finish(n,field,meaning),file=['Uni-05 - ' n ' v2.png'];pubfig.export(gcf,fullfile(dest,file));close(gcf);catalog(end+1)=struct('file',file,'field',field,'meaning',meaning);end
end
